/*
  # ONE-TIME IMPORT of the 35 listings exported from the pre-refactor Supabase project.

  Run in the SQL editor of the NEW project AFTER all files in supabase/migrations/ have been run.
  Safe to run twice (rows whose id or slug already exist are skipped).

  What it does
    1. creates a scratch table `properties_legacy` shaped like the old one
    2. loads the exported rows into it
    3. runs the legacy -> normalized migration (same logic as 20261110000500_migrate_legacy_data.sql)
    4. drops the scratch table

  Buy-only: Rent rows in the export are skipped (reported in the NOTICE output).
  Amenity names are folded into the filterable ones (Gymnasium -> Gym, Elevator -> Lift, ...).
*/

DROP TABLE IF EXISTS properties_legacy;
CREATE TABLE properties_legacy (
  id uuid, title text, slug text, city text, locality text, property_type text, listing_type text,
  price numeric, bedrooms integer, bathrooms integer, min_area_sqft integer, max_area_sqft integer,
  description text, image_url text, gallery jsonb, amenities jsonb, furnishing text, parking integer,
  floor_number integer, total_floors integer, age_years integer, builder text, builder_logo text,
  rera_id text, featured boolean, exclusive boolean, status text, created_at timestamptz,
  nearby jsonb, floor_plans jsonb, configurations jsonb
);
ALTER TABLE properties_legacy ENABLE ROW LEVEL SECURITY;

